package app.vidloader;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.lang.reflect.*;import org.json.*;import android.content.Context;
public final class DesktopBridge{
 private static final Map<String,CompletableFuture<JSONObject>> pending=new ConcurrentHashMap<>();private static final ExecutorService jobs=Executors.newFixedThreadPool(6);private static final Map<String,Future<?>> running=new ConcurrentHashMap<>();
 private static final Map<String,MediaCandidate> choices=new ConcurrentHashMap<>();private static Context context=new Context();private static DownloadService service;
 public static synchronized void emit(JSONObject data){System.out.println(data.toString());System.out.flush();}
 public static JSONObject ask(String op,JSONObject payload)throws Exception{if(Thread.currentThread().isInterrupted())throw new InterruptedException("Browser platform request cancelled");String id=UUID.randomUUID().toString();CompletableFuture<JSONObject> f=new CompletableFuture<>();pending.put(id,f);emit(new JSONObject().put("event","platform").put("op",op).put("id",id).put("data",payload));try{JSONObject r=f.get(25,TimeUnit.SECONDS);if(r.has("error"))throw new IOException(r.optString("error"));return r;}catch(InterruptedException e){Thread.currentThread().interrupt();throw e;}finally{pending.remove(id);}}
 public static void main(String[] args)throws Exception{Context.root=new File(args[0]);Context.assets=new File(args[1]);Context.root.mkdirs();Context.settings.put("browserSession",args.length>2?args[2]:"desktop");if(args.length>3){JSONObject initial=new JSONObject(args[3]);Iterator<String> keys=initial.keys();while(keys.hasNext()){String k=keys.next();if(Arrays.asList("parallel","destination").contains(k))Context.settings.put(k,initial.get(k));}}service=new DownloadService();emit(new JSONObject().put("event","ready"));BufferedReader reader=new BufferedReader(new InputStreamReader(System.in,StandardCharsets.UTF_8));String line;while((line=reader.readLine())!=null){if(line.length()>16*1024*1024)continue;JSONObject m;try{m=new JSONObject(line);}catch(Exception e){continue;}String type=m.optString("type");if(type.equals("reply")){CompletableFuture<JSONObject> f=pending.get(m.optString("id"));if(f!=null){JSONObject reply=m.optJSONObject("data");if(reply==null)f.completeExceptionally(new IOException("Invalid browser platform reply"));else f.complete(reply);}continue;}if(type.equals("helperEvent")){final JSONObject event=m;jobs.submit(()->android.webkit.WebView.event(event.optString("view"),event.optString("method"),event.optString("value")));continue;}if(m.optString("op").equals("cancel")){Future<?> f=running.remove(m.optString("target"));if(f!=null)f.cancel(true);continue;}final JSONObject request=m;String id=m.optString("id");try{submitRequest(id,()->{try{Object result=handle(request.optString("op"),request.optJSONObject("data"));emit(new JSONObject().put("id",id).put("result",result));}catch(Throwable e){emit(new JSONObject().put("id",id).put("error",YoutubeResolver.safeError(e)));}return null;});}catch(IllegalArgumentException e){emit(new JSONObject().put("id",id).put("error",e.getMessage()));}}service.onDestroy();System.exit(0);}
 static Future<?> submitRequest(String id,Callable<Void> action){FutureTask<Void> task=new FutureTask<Void>(action){@Override protected void done(){running.remove(id,this);}};Future<?> previous=running.putIfAbsent(id,task);if(previous!=null)throw new IllegalArgumentException("Duplicate engine request identity");try{jobs.execute(task);}catch(RuntimeException e){running.remove(id,task);throw e;}return task;}
 static Object handle(String op,JSONObject data)throws Exception{if(data==null)data=new JSONObject();switch(op){
 case "settings":{Iterator<String> k=data.keys();while(k.hasNext()){String key=k.next();if(Arrays.asList("parallel","destination","browserSession").contains(key))Context.settings.put(key,data.get(key));}DownloadService.command(context,DownloadService.RECONFIGURE,"");return true;}
 case "queue":{JSONArray list=new JSONArray();for(DownloadStore.Task t:DownloadStore.get(context).all()){JSONObject j=t.json();j.remove("cookie");j.remove("extractorHeaders");j.remove("audioExtractorHeaders");j.remove("youtubeSabr");j.put("speed",t.bytesPerSecond).put("active",t.active).put("path",DownloadStore.get(context).file(t).getAbsolutePath());list.put(j);}return list;}
 case "command":{String action=data.optString("action");if(!Arrays.asList("pause","resume","cancel","reconfigure").contains(action))throw new IOException("Invalid queue action");DownloadService.command(context,action,data.optString("id"));return true;}
 case "rename":{DownloadStore st=DownloadStore.get(context);DownloadStore.Task t=st.find(data.optString("id"));if(t==null||!t.state.equals("completed"))throw new IOException("Completed file not found");File original=st.file(t);String nextName=DownloadStore.safeName(data.optString("name"));File renamed=new File(original.getParentFile(),t.id+"-"+nextName);String exportedUri=new File(data.optString("path")).toURI().toString();if(original.isFile()&&!original.equals(renamed))java.nio.file.Files.move(original.toPath(),renamed.toPath());t.name=nextName;t.exportedUri=exportedUri;st.save();return true;}
 case "remove":{DownloadStore store=DownloadStore.get(context);DownloadStore.Task t=store.find(data.optString("id"));if(t==null)return true;if(t.active)throw new IOException("Pause the download and wait before removing it");if(data.optBoolean("delete")){java.nio.file.Files.deleteIfExists(store.file(t).toPath());if(!t.exportedUri.isEmpty()){File exported=new File(java.net.URI.create(t.exportedUri));if(exported.isFile())java.nio.file.Files.delete(exported.toPath());}}java.nio.file.Files.deleteIfExists(store.partial(t).toPath());File work=store.work(t);try(java.util.stream.Stream<java.nio.file.Path> paths=java.nio.file.Files.walk(work.toPath())){for(java.nio.file.Path path:paths.sorted(java.util.Comparator.reverseOrder()).toList())java.nio.file.Files.deleteIfExists(path);}store.remove(t.id);return true;}
 case "vkRequest":return DesktopSites.vk(data);
 case "contractTests":return EngineContractTests.run(context);
 case "popup":{BrowserProtection p=protection();return data.optBoolean("enabled",true)&&p.shouldBlockPopup(data.optString("source"),data.optString("target"),data.optBoolean("gesture"));}
 case "diagnostics":return YoutubeDiagnostics.read(context);
 case "extract":{String page=web(data.optString("page"));List<MediaCandidate> found;if(YoutubeMedia.isFeaturePage(page))found=YoutubeResolver.resolve(context,page,data.optBoolean("refresh"),stage->emit(new JSONObject().put("event","stage").put("text",stage)));else{found=new ArrayList<>();try{found.addAll(DesktopSites.extract(page,data.optString("title"),data.optString("userAgent"),data.optJSONObject("capturedHeaders")));}catch(Exception siteError){YoutubeDiagnostics.record(context,"desktop-site",YoutubeResolver.safeError(siteError));}JSONArray resources=data.optJSONArray("resources");if(resources!=null)for(int i=0;i<resources.length()&&i<1500;i++){JSONObject r=resources.optJSONObject(i);if(r==null||r.optBoolean("advertisement"))continue;MediaCandidate c=resourceCandidate(r.optString("url"),r.optString("mime"),r.optString("title",data.optString("title")),r.optString("source","Browser"));if(c!=null){c=new MediaCandidate(c.url,c.title,c.mime,r.optInt("width"),r.optInt("height"),c.source,c.kind,c.bandwidth,c.codecs,c.audioGroup,c.audioUrl,c.drm,c.initUrl,c.segments,c.audioInitUrl,c.audioSegments,c.unsupportedReason,c.manifestUrl);c.contentLength=r.optLong("bytes",-1);c.qualityHint=r.optBoolean("qualityHint");c.responseVerified=r.optBoolean("playbackVerified");c.durationMs=r.optLong("durationMs");c.thumbnailUrl=r.optString("thumbnail");c.referer=page;c.origin=origin(page);c.userAgent=data.optString("userAgent");found.add(c);}}
 if(found.isEmpty()){MediaCandidate c=MediaParser.fromUrl(page,"",data.optString("title","Media"),"Address");if(c!=null)found.add(c);}
 List<MediaCandidate> expanded=new ArrayList<>();for(MediaCandidate c:found){if(c.kind==MediaCandidate.Kind.HLS_MASTER||c.kind==MediaCandidate.Kind.HLS_MEDIA||c.kind==MediaCandidate.Kind.DASH){try{Map<String,String> h=new HashMap<>();h.put("Referer",page);h.put("User-Agent",data.optString("userAgent"));java.net.HttpURLConnection conn=HttpMedia.open(c.url,h,x->{x.setConnectTimeout(7000);x.setReadTimeout(7000);});String manifest;try(InputStream in=conn.getInputStream()){manifest=new String(YoutubeIO.readAll(in,8*1024*1024),StandardCharsets.UTF_8);}finally{conn.disconnect();}List<MediaCandidate> parsed=c.kind==MediaCandidate.Kind.DASH?MediaParser.parseDash(manifest,c.url,c.title):MediaParser.parseHls(manifest,c.url,c.title);for(MediaCandidate x:parsed){x.referer=page;x.origin=origin(page);x.userAgent=c.userAgent;}expanded.addAll(parsed);}catch(Exception e){expanded.add(c);}}else expanded.add(c);}found=MediaSelection.choices(expanded,false);}
 JSONArray output=new JSONArray();Set<String> unique=new HashSet<>();for(MediaCandidate c:found){if(c.drm||!c.unsupportedReason.isEmpty())continue;String key=c.kind+":"+c.url+":"+c.audioUrl+":"+c.youtubeFormatId;if(!unique.add(key))continue;String id=UUID.randomUUID().toString();if(choices.size()>5000)choices.clear();choices.put(id,c);JSONObject j=serialize(c);j.put("choice",id);output.put(j);}return output;}
 case "enqueue":{MediaCandidate c=choices.get(data.optString("choice"));if(c==null)throw new IOException("Inspect formats again before downloading");web(c.url);DownloadStore.Task t=new DownloadStore.Task();t.url=c.url;t.title=c.title;t.mime=c.mime;t.name=DownloadStore.safeName(data.optString("name",c.title))+extension(c,data.optBoolean("mp3"));if(t.name.matches("(?i).*\\.(mp4|webm|m4a|mp3|srt|opus)\\.(mp4|webm|m4a|mp3|srt|opus)$"))t.name=t.name.substring(0,t.name.lastIndexOf('.'));t.kind=c.kind.name();t.audioUrl=c.audioUrl;t.initUrl=c.initUrl;t.audioInitUrl=c.audioInitUrl;t.segments=new ArrayList<>(c.segments);t.audioSegments=new ArrayList<>(c.audioSegments);t.referer=c.referer;t.origin=c.origin;t.userAgent=c.userAgent;t.cookie=Optional.ofNullable(android.webkit.CookieManager.getInstance().getCookie(c.url)).orElse("");t.thumbnailUrl=c.thumbnailUrl;t.durationMs=c.durationMs;t.total=c.contentLength;t.mp3Output=data.optBoolean("mp3");t.mp3Bitrate=data.optInt("bitrate",128);t.youtubeFormatId=c.youtubeFormatId;t.youtubeAudioFormatId=c.youtubeAudioFormatId;t.youtubeChunkSize=c.youtubeChunkSize;t.youtubeAudioChunkSize=c.youtubeAudioChunkSize;t.youtubeSabr=c.youtubeSabr;t.extractorHeaders.putAll(c.extractorHeaders);t.audioExtractorHeaders.putAll(c.audioExtractorHeaders);if(YoutubeMedia.isFeaturePage(c.referer))t.youtubePage=c.referer;DownloadService.add(context,t);JSONArray captions=data.optJSONArray("captions");if(captions!=null){JSONArray available=new JSONArray(c.youtubeCaptions);for(int i=0;i<available.length();i++){JSONObject caption=available.getJSONObject(i);for(int k=0;k<captions.length();k++)if(caption.optString("id").equals(captions.optString(k))){MediaCandidate cc=YoutubeCaptions.output(caption,c);String id=UUID.randomUUID().toString();choices.put(id,cc);handle("enqueue",new JSONObject().put("choice",id).put("name",cc.title));}}}return t.id;}
 case "protection":{BrowserProtection protection=protection();JSONArray urls=data.optJSONArray("urls"),out=new JSONArray();for(int i=0;i<urls.length();i++)out.put(protection.isAdUrl(urls.getString(i)));return out;}
 default:throw new IOException("Unknown engine operation");}}
 private static BrowserProtection rules;
 static synchronized BrowserProtection protection()throws Exception{if(rules==null){rules=new BrowserProtection(new InputStreamReader(context.getAssets().open("browser_hosts.txt"),StandardCharsets.UTF_8));rules.addHosts(new InputStreamReader(context.getAssets().open("browser_threat_hosts.txt"),StandardCharsets.UTF_8));}return rules;}
 static MediaCandidate resourceCandidate(String url,String mime,String title,String source){String type=mime==null?"":mime.split(";",2)[0].trim().toLowerCase(Locale.ROOT);if(type.equals("video/unknown")||type.equals("audio/unknown")){MediaCandidate inferred=MediaParser.fromUrl(url,"",title,source);if(inferred!=null)return inferred;}return MediaParser.fromUrl(url,mime,title,source);}
 static String extension(MediaCandidate c,boolean mp3){if(mp3)return ".mp3";if(c.mime.equals("application/x-subrip"))return ".srt";if(c.mime.contains("webm"))return ".webm";if(c.mime.contains("opus"))return ".opus";if(c.mime.startsWith("audio/"))return c.mime.contains("mpeg")?".mp3":".m4a";return ".mp4";}
 static JSONObject serialize(MediaCandidate c)throws Exception{JSONObject j=new JSONObject();for(Field f:MediaCandidate.class.getFields()){if(Modifier.isStatic(f.getModifiers())||(f.getName().contains("Headers")||f.getName().equals("youtubeSabr")))continue;Object v=f.get(c);if(v instanceof Double&&!Double.isFinite((Double)v)||v instanceof Float&&!Float.isFinite((Float)v)){j.put(f.getName(),JSONObject.NULL);continue;}if(v instanceof Enum)v=v.toString();if(v instanceof Collection)v=new JSONArray((Collection<?>)v);j.put(f.getName(),v);}return j;}
 static String origin(String s){java.net.URI u=java.net.URI.create(s);return u.getScheme()+"://"+u.getRawAuthority();}
 static String web(String s)throws IOException{try{java.net.URI u=java.net.URI.create(s);if(!Arrays.asList("http","https").contains(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null)throw new Exception();return s;}catch(Exception e){throw new IOException("Only HTTP or HTTPS media addresses are accepted");}}
}